import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    recent = history[-12:] if n >= 12 else history
    rlen = len(recent)
    opp_recent_c = 0
    opp_recent_d = 0
    for _, o in recent:
        if o == 'C':
            opp_recent_c += 1
        else:
            opp_recent_d += 1

    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    opp_rate = opp_c / n
    recent_rate = opp_recent_c / rlen

    # If opponent never defected, cooperate but grab a little late profit.
    if opp_d == 0:
        if n >= 97:
            return 'D'
        return 'C'

    # Detect relentless defector: defect and don't waste rounds cooperating.
    if opp_d >= 3 and opp_recent_d >= rlen - 1 and opp_c <= 2:
        return 'D'

    # Detect a long current defection streak.
    streak = 0
    for _, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break

    # Long mutual defection: try a single cooperative repair move.
    if streak >= 3:
        if my_last == 'D' and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: preserve mutual cooperation.
    if recent_rate >= 0.75:
        if opp_last == 'C':
            return 'C'
        # Opponent just defected; usually punish, but forgive an isolated blip.
        if opp_recent_d <= 1:
            return 'C' if rng.random() < 0.6 else 'D'
        return 'D'

    # Strongly defecting recently: retaliate hard.
    if recent_rate <= 0.25:
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Mixed regime: tit-for-tat with forgiveness and repair.
    if opp_last == 'D':
        if my_last == 'D':
            # Alternating retaliation: try to break the cycle.
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # We cooperated, they defected. Punish once, but forgive if rare overall.
        if opp_d <= 2 and n >= 8:
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D'

    # Opponent cooperated.
    if my_last == 'D':
        # We just punished; return to cooperation to support recovery.
        return 'C'
    # Sometimes exploit a moderately cooperative opponent near the end.
    if n >= 90 and opp_rate > 0.55:
        return 'D' if rng.random() < 0.4 else 'C'
    return 'C'
